//! Rust-facing translation of `trace/events/btrfs.h`.
//!
//! The original file is a Linux tracepoint declaration header.  Its
//! `TRACE_EVENT`, `DECLARE_EVENT_CLASS`, and `DEFINE_EVENT` forms are
//! generated by the kernel tracing framework and therefore have no standalone
//! Rust ABI.  The declarations below preserve the header's named interface;
//! event payload layouts and assignment/printing expressions remain external
//! tracepoint-framework definitions, exactly as they are in the C header.

#![allow(non_camel_case_types, non_snake_case, non_upper_case_globals)]

// Forward declarations from the C header.  Definitions are supplied by the
// kernel translation unit that consumes this header.
