pub enum extent_buffer {}
pub enum btrfs_work {}
pub enum btrfs_workqueue {}
pub enum btrfs_qgroup_extent_record {}
pub enum btrfs_qgroup {}
pub enum extent_io_tree {}
pub enum prelim_ref {}
pub enum btrfs_space_info {}
pub enum btrfs_raid_bio {}
pub enum raid56_bio_trace_info {}
pub enum find_free_extent_ctl {}
pub enum btrfs_trans_handle {}
pub enum btrfs_transaction {}
pub enum btrfs_log_ctx {}

pub const BTRFS_FSID_SIZE: usize = 16;

/// Symbolic mapping used by the C `show_inode_type` trace helper.
